    constructor() {
        this.isPaused = false;
        document.addEventListener('keydown', this.handleKeyDown.bind(this));
    }

    handleKeyDown(event) {
        if (event.key === 'p' || event.key === 'P') {
            this.togglePause();
        }
    }

    togglePause() {
        this.isPaused = !this.isPaused;
        console.log(`Game is ${this.isPaused ? 'paused' : 'running'}`);
    }
}

